void sb_queue_Exhaustive_Monitor_Samples_1_enqueue(
  sb_queue_Exhaustive_Monitor_Samples_1_t *queue,
  Exhaustive_Monitor_Samples *data) {

  // Simple ring with one dirty element that will be written next. Only one
  // writer, so no need for any synchronization.
  // elt[queue->numSent % SB_QUEUE_EXHAUSTIVE_MONITOR_SAMPLES_1_SIZE]
  // is always considered dirty. So do not advance queue->NumSent
  // till AFTER data is copied.

  size_t index = queue->numSent % SB_QUEUE_EXHAUSTIVE_MONITOR_SAMPLES_1_SIZE;

  memcpy(&queue->elt[index], data, Exhaustive_Monitor_Samples_BYTE_SIZE); // Copy data into queue

  // Release memory fence - ensure that data write above completes BEFORE we advance queue->numSent
  __atomic_thread_fence(__ATOMIC_RELEASE);

  ++(queue->numSent);
}

bool sb_queue_Exhaustive_Monitor_Samples_1_peek_latest(
  sb_queue_Exhaustive_Monitor_Samples_1_t *queue,
  Exhaustive_Monitor_Samples *data) {

  sb_event_counter_t numSent = queue->numSent;
  if (0 == numSent) {
    return false;
  }

  // Position a temporary receiver immediately before the latest committed
  // enqueue. Reading through the dequeue algorithm preserves its coherence
  // checks without changing any real receiver's cursor.
  sb_queue_Exhaustive_Monitor_Samples_1_Recv_t snapshot = {
    .numRecv = numSent - 1,
    .queue = queue
  };
  sb_event_counter_t numDropped;
  return sb_queue_Exhaustive_Monitor_Samples_1_dequeue(&snapshot, &numDropped, data);
}

