        *value = v;
        return true;
      },
      None => return false,
    }
  }
}

#[cfg(test)]
pub fn get_ack() -> bool
{
  unsafe {
    match *IN_ack.lock().unwrap_or_else(|e| e.into_inner()) {
      Some(v) => {
        return true;
      },
      None => return false,
    }
  }
}

